from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)

    destination = list(range(n + 1))
    for cell in range(n + 1):
        target = cell
        while target in jump_to:
            target = jump_to[target]
        destination[cell] = target

    transitions = [{} for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        counts = transitions[cell]
        for roll in range(1, m + 1):
            target = cell + roll
            if target > n:
                target = 2 * n - target
            target = destination[target]
            counts[target] = counts.get(target, 0) + 1

        for target in counts:
            reverse[target].append(cell)

    reachable = {0}
    queue = [0]
    for cell in queue:
        for target in transitions[cell]:
            if target not in reachable:
                reachable.add(target)
                queue.append(target)

    can_finish = {n}
    queue = [n]
    for cell in queue:
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # m * E[cell] - sum(count * E[target]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for i, cell in enumerate(states):
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    # Bareiss elimination keeps all intermediate entries integral.
    # This transient Markov-chain matrix has nonzero leading pivots.
    previous_pivot = 1
    for column in range(size - 1):
        pivot_row = matrix[column]
        pivot = pivot_row[column]

        for i in range(column + 1, size):
            row = matrix[i]
            factor = row[column]
            for j in range(column + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[column] = 0

        previous_pivot = pivot

    expectation = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            if matrix[i][j]:
                value -= matrix[i][j] * expectation[j]
        expectation[i] = value / matrix[i][i]

    result = expectation[index[0]]
    return [result.numerator, result.denominator]
